) }}</th><th>{{ $config['page']==='users'?'Penugasan aktif':($config['page']==='employees'?'Unit':'Kode') }}</th><th>Status</th><th>Tindakan</th></tr>@endif</thead><tbody><template x-for="row in rows" :key="row.id"><tr>@if($config['page']==='audit')<td class="small" x-text="ui.dateTime(row.recorded_at)"></td><td><strong x-text="ui.actionLabel(row.action)"></strong><span class="subtext" x-text="row.reason || ''"></span></td><td x-text="actor(row.actor_user_id)"></td><td x-text="row.status_after ? ui.status(row.status_after) : 'Tercatat'"></td><td><button class="btn btn-small" @click="showAudit(row)">Lihat detail</button></td>@else<td><strong x-text="row.full_name || row.name"></strong><span class="subtext" x-text="row.nip || row.email || row.login_nip || row.code"></span></td><td>@if($config['page']==='users')<span x-text="userRoles(row.id).map(r=>ui.roleName(r)).join(', ') || 'Belum ada'"></span>@elseif($config['page']==='employees')<span x-text="positionName(row.position_id)"></span>@else<span x-text="row.is_active?'Aktif':'Nonaktif'"></span>@endif</td><td>@if($config['page']==='users')<span x-text="assignmentNames(row.id)"></span>@elseif($config['page']==='employees')<span x-text="placement(row.id)?.unit_name || 'Belum ditempatkan'"></span>@else<span x-text="row.code"></span>@endif</td><td><x-badge value="row.is_active ? 'active' : 'inactive'"/></td><td><div class="button-row"><button class="btn btn-small" @click="edit(row)">Ubah</button>@if($config['page']==='employees')<button class="btn btn-small" @click="transfer(row)">Atur penempatan</button>@elseif($config['page']==='users')<button class="btn btn-small" x-show="userRoles(row.id).includes('super_hc') && assignmentNames(row.id)==='Belum ditugaskan'" @click="grantHc(row)">Berikan akses HC</button><button class="btn btn-small" x-show="row.id!==ui.user.id && assignmentNames(row.id)!=='Belum ditugaskan'" @click="revokeUser(row)">Cabut penugasan</button>@endif</div></td>@endif</tr></template></tbody></table></div><x-pagination/></div>@if($config['page']!=='audit')<x-record-form/>@else<dialog x-ref="audit" @click.self="$el.close()"><div class="dialog-body"><div class="dialog-header"><h2>Detail aktivitas</h2><button class="icon-button" @click="$refs.audit.close()" aria-label="Tutup aktivitas"><x-icon name="close"/></button></div><template x-if="auditRow"><div class="stack"><strong x-text="ui.actionLabel(auditRow.action)"></strong><p x-text="actor(auditRow.actor_user_id)+' · '+ui.dateTime(auditRow.recorded_at)"></p><p x-text="auditRow.reason || 'Tidak ada catatan tambahan.'"></p><div class="notice" x-show="auditRow.status_before || auditRow.status_after"><span x-text="ui.status(auditRow.status_before)"></span> → <span x-text="ui.status(auditRow.status_after)"></span></div><a class="btn" x-show="auditRow.assessment_id" :href="ui.link('assessments/'+auditRow.assessment_id)">Buka lembar penilaian</a></div></template></div></dialog>@endif</section>
